package hr.algebra.sitelog.common.domain;

import org.hibernate.Hibernate;

import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;

/**
 * Surrogate key shared by every entity: each table has {@code id bigint GENERATED BY DEFAULT AS
 * IDENTITY} (see the Flyway migrations).
 *
 * <p>Equality is by id: two instances are equal when they have the same class and the same,
 * non-null id. A new (not yet persisted) entity is only equal to itself. {@code hashCode} is
 * constant per class so it does not change when the id is assigned on flush, which keeps
 * entities in a {@code Set} findable before and after persisting. {@link Hibernate#getClass}
 * unwraps lazy proxies, so a proxy and the loaded entity compare as equal.
 */
@MappedSuperclass
public abstract class BaseEntity {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	public Long getId() {
		return id;
	}

	@Override
	public boolean equals(Object other) {
		if (this == other) {
			return true;
		}
		if (other == null || Hibernate.getClass(this) != Hibernate.getClass(other)) {
			return false;
		}
		Long otherId = ((BaseEntity) other).getId();
		return getId() != null && getId().equals(otherId);
	}

	@Override
	public int hashCode() {
		return Hibernate.getClass(this).hashCode();
	}

}
